from taf.collectors.core import core
from taf.collectors.browser_server.factory import L2Trace3gCollectorFactory, BrowserServerFactory, \
    CellThroughputCollectorFactory
from robot.utils.robottypes import is_truthy

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class browser_server(core):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def create_browser_server(self,
                              name,
                              bts_host='192.168.255.129',
                              bts_port=15003,
                              enable_extra_log=None):
        """
        Create Browser Server client, which will be used by L2 trace 3G collector and cell throughput collector.

        :param str name: alias name of the collector
        :param str bts_host: BTS ip address (192.168.255.129 is default)
        :param int bts_port: BTS port to connect to (15003 is default)
        :param bool enable_extra_log: (Optional) If set to True, a special library log will be collected
            in ~/taf.sbts.browser_server_logs, default value is False

        Please refer example mentioned in create_l2trace_3g_collector/create_cell_throughput for usage.
        """
        configuration = {"name": name,
                         "enable_extra_log": is_truthy(enable_extra_log)}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["bts_host", "bts_port",
                                  "enable_extra_log"] and parameter_value is not None:
                configuration[parameter_name] = parameter_value
        logger.info("Creating browser server with alias name: %s", name)
        browser_server_3g = BrowserServerFactory().create(
            configuration=configuration, existing_arguments={})
        logger.info("browser server created successfully")
        self.set_alias(name, browser_server_3g)

    def _create_configuration(self,
                              name,
                              tool,
                              cell_id,
                              target_file_name=None,
                              as_zip=None):
        configuration = {"name": name,
                         "cell_id": int(cell_id),
                         "tool": self.get_alias_value(tool)}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["target_file_name", "as_zip"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value
        return configuration

    def create_cell_throughput_collector(self,
                                         name,
                                         tool,
                                         cell_id,
                                         target_file_name=None,
                                         as_zip=None):
        """
        Create cell throughput for Sbts from given configuration

        :param str name: alias name of the collector
        :param str tool: alias of previously created Browser Server client.
        :param int/str cell_id: WCDMA cell id
        :param bool as_zip: (optional) default True
        :param str target_file_name: (optional) file name part of the path under which the zip file is
                                        stored locally during collect_collectors, default: "cell_throughput.zip"
        """
        configuration = self._create_configuration(name=name,
                                                   tool=tool,
                                                   cell_id=cell_id,
                                                   target_file_name=target_file_name,
                                                   as_zip=as_zip)
        logger.info("Creating cell throughput collector with alias name: %s", name)
        cell_throughput = CellThroughputCollectorFactory().create(
            configuration=configuration,
            existing_arguments={})
        logger.info("ccell throughput collector created successfully")
        self.set_alias(name, cell_throughput)

    def create_l2trace_3g_collector(self,
                                    name,
                                    tool,
                                    cell_id,
                                    target_file_name=None,
                                    as_zip=None):
        """
        Create l2trace 3G Collector for Sbts from given configuration

        :param str name: alias name of the collector
        :param str tool: alias of previously created Browser Server client.
        :param int/str cell_id: WCDMA cell id
        :param bool as_zip: (optional) default True
        :param str target_file_name: (optional) file name part of the path under which the zip file is
                                        stored locally during collect_collectors, default: "l2trace_3g.zip"
        """
        configuration = self._create_configuration(name=name,
                                                   tool=tool,
                                                   cell_id=cell_id,
                                                   target_file_name=target_file_name,
                                                   as_zip=as_zip)
        logger.info("Creating l2trace 3G collector with alias name: %s", name)
        l2trace_3g = L2Trace3gCollectorFactory().create(
            configuration=configuration, existing_arguments={})
        logger.info("l2trace 3G Collector created successfully")
        self.set_alias(name, l2trace_3g)
